  id: "neco-vs-waec-which-should-you-write",
  title: "NECO vs WAEC: Are They Really Different and Which Should You Write?",
  category: "waec",
  categoryLabel: "WAEC",
  author: "Michael Joseph",
  authorAvatar: "avatar_1",
  publishAt: "2026-10-25T06:00:00+01:00",
  updatedAt: "2026-10-21T08:00:00+01:00",
  readTime: 6,
